        "name": "Applications Demo",
        "code": "#!/usr/bin/env python3\n\"\"\"Self-contained applications demo for Erd\u0151s\u2013Szekeres theory.\"\"\"\nimport random\nimport bisect\nfrom typing import List, Tuple, Optional\n\nPoint = Tuple[float, float]\n\ndef orient(a: Point, b: Point, c: Point) -> float:\n    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])\n\ndef longest_increasing_subsequence_fast(seq):\n    n = len(seq)\n    if n == 0: return []\n    tails, parent, indices = [], [-1]*n, []\n    for i in range(n):\n        pos = bisect.bisect_left(tails, seq[i])\n        if pos == len(tails):\n            tails.append(seq[i]); indices.append(i)\n        else:\n            tails[pos] = seq[i]; indices[pos] = i\n        if pos > 0: parent[i] = indices[pos-1]\n    result, idx = [], indices[len(tails)-1]\n    while idx != -1: result.append(idx); idx = parent[idx]\n    return result[::-1]\n\ndef longest_decreasing_subsequence_fast(seq):\n    return longest_increasing_subsequence_fast([-x for x in seq])\n\n# Application: Financial trend detection\nprint(\"Financial Trend Detection\")\nprint(\"=\" * 50)\nrandom.seed(42)\nprices = [100.0]\nfor _ in range(49):\n    prices.append(prices[-1] + random.gauss(0.1, 2))\ninc = longest_increasing_subsequence_fast(prices)\ndec = longest_decreasing_subsequence_fast(prices)\nprint(f\"Price series: {len(prices)} points\")\nprint(f\"Longest uptrend: {len(inc)} days\")\nprint(f\"Longest downtrend: {len(dec)} days\")\nprint(f\"ES guarantee: any 17+ days must have monotone trend of length 5\")\n\n# Application: Quality control\nprint(\"\nQuality Control Drift Detection\")\nprint(\"=\" * 50)\nrandom.seed(123)\nmeasurements = [10.0 + 0.02*i + random.gauss(0, 0.1) for i in range(30)]\ninc = longest_increasing_subsequence_fast(measurements)\nprint(f\"Measurements: {len(measurements)} samples\")\nprint(f\"Drift detected: {len(inc) >= 5} (trend length {len(inc)})\")\n"
